                          !form.date ||
                          form.date <= today ||
                          'Effective date cannot be in the future',
                      ]"
                      hint="Defaults to the planned transfer date — cannot be in the future"
                      persistent-hint
                      v-bind="attrs"
                      v-on="on"
                    ></v-text-field>
                  </template>
                  <v-date-picker
                    v-model="form.date"
                    :max="today"
                    @input="effectiveDateMenu = false"
                  ></v-date-picker>
                </v-menu>
              </v-card-text>
              <v-card-actions class="pa-4 pt-0">
                <v-btn text small @click="goBack">Cancel</v-btn>
                <v-spacer></v-spacer>
                <v-btn color="primary" small @click="openConfirmDialog">
                  <v-icon left small>mdi-check-decagram</v-icon>Apply Transfer
                </v-btn>
              </v-card-actions>
            </v-card>
          </div>
        </aside>
      </div>
    </template>

    <v-snackbar
      v-model="snackbar.show"
      :color="snackbar.color"
      top
      right
      :timeout="4000"
    >
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import store from "@/store";
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import transferReview from "./transferReview";

// ── Backend contract (for whoever implements the workflow) ────────────────
// POSTs via processFHIR() to /fhir/QuestionnaireResponse with:
//   - questionnaire: "http://ihris.org/fhir/Questionnaire/apply-hod-recommended-transfer"
//   - flat body fields:
//       request: "<transfer Basic id>"
//       supervisor: "<new supervisor Practitioner id>" (bare id, not "Practitioner/id")
//       comments: string (optional notes)
//       date: "YYYY-MM-DD" (effective date)
// Expected server-side responsibilities (not built here — UI only):
//   - reject unless the transfer's request-status is the PS-approved code
//     ("psapproved")
//   - reject unless the requester matches the transfer's user-reference
//     (the HOD Director who originally submitted it)
//   - re-check the destination position still has a vacancy before acting
//   - end the staff member's current PractitionerRole and create the new
//     one at the destination position, with `supervisor` as the new role's
//     supervisor extension (reuse the existing assign/terminate position
//     workflow logic rather than duplicating it)
//   - set the transfer's request-status to a terminal "applied"/"transferred"
//     code so this page and the list button stop showing it as actionable

export default {
  name: "HodApplyTransfer",
  mixins: [generalMixin, processQuestionnaire, transferReview],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/apply-hod-recommended-transfer",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/hod-recommended-transfer-profile",

      confirmDialog: false,
      effectiveDateMenu: false,

      stageConfig: {
        reviewerCode: null,
        expectedStatus: "psapproved",
        label: "HOD Director",
        // Only the HOD Director who originally submitted this recommendation
        // (transfer.requesterUserRef, a Person reference) may apply it —
        // compared against the logged-in Person id from the Vuex store
        // (the same resource generalMixin reads the practitioner ref from).
        checkAuthorized: async (ctx) => {
          try {
            const loggedInPersonId = store.state.user?.obj?.resource?.id;
            if (!loggedInPersonId) return false;
            const requesterId = ctx.refId(ctx.transfer.requesterUserRef);
            if (!requesterId) return false;
            return String(requesterId) === String(loggedInPersonId);
          } catch (err) {
            console.error("HOD Director access check failed:", err);
            return false;
          }
        },
      },

      form: {
        comments: "",
        date: new Date().toISOString().substr(0, 10),
        supervisor: {
          reference: null,
          display: "",
          position: "",
          facility: "",
          grade: "",
        },
      },

      // ── Supervisor picker ──────────────────────────────────────────────
      supervisorDialog: false,
      supervisorItems: [],
      supervisorTotal: 0,
      loadingSupervisors: false,
      supervisorOptions: { page: 1, itemsPerPage: 10 },
      supFilter: { name: "", position: "", department: null },
      supDebounce: null,
      supFilterTreeOpen: false,
      supervisorHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        {
          text: "Employment Category",
          value: "employmentCategory",
          sortable: false,
        },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],
      departmentOptions: [],

      // Location filter tree, shared with the supervisor picker dialog.
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {}, // 'Location/id' → { name, type: 'district'|'council'|'facility' }
        loading: false,
        displayValue: "",
      },
    };
  },

  computed: {
    initials() {
      if (!this.staffName) return "?";
      return this.staffName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    wasRejected() {
      const status = this.transfer.status || "";
      return status.includes("rejected") || status === "cancelled";
    },

    // Anything other than "awaiting/under review", "rejected", or the
    // PS-approved trigger status is treated as already actioned — this
    // deliberately doesn't hardcode the eventual terminal status code
    // (e.g. "transferred"), since that's set by the backend workflow.
    alreadyApplied() {
      const status = this.transfer.status || "";
      if (!status) return false;
      if (status === this.stageConfig.expectedStatus) return false;
      if (this.wasRejected) return false;
      if (status.includes("review")) return false;
      return true;
    },

    canApply() {
      return (
        this.isAuthorized &&
        this.transfer.status === this.stageConfig.expectedStatus
      );
    },

    today() {
      return new Date().toISOString().substr(0, 10);
    },
  },

  watch: {
    // Default to the planned transfer date — but only if it's not in the
    // future (the effective date can never be in the future), otherwise
    // fall back to today.
    "transfer.plannedTransferDate"(val) {
      if (!val || this.form.date) return;
      this.form.date = val <= this.today ? val : this.today;
    },

    "filterTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filterTree.displayValue = id
        ? this.filterTree.treeLookup[id]?.name || id
        : "";
      this.fetchSupervisors();
    },

    supervisorOptions: {
      handler() {
        if (this.supervisorDialog) this.fetchSupervisors();
      },
      deep: true,
    },
  },

  async mounted() {
    await Promise.all([this.loadValueSets(), this.loadFilterTree()]);
  },

  methods: {
    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    async loadValueSets() {
      try {
        const dept = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/departments-valueset",
        );
        this.departmentOptions = (dept || []).map((c) => ({
          system: c.system,
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadValueSets error", err);
      }
    },

    // ── Supervisor picker ──────────────────────────────────────────────
    openSupervisorDialog() {
      this.supervisorDialog = true;
      this.fetchSupervisors();
    },

    debouncedFetchSupervisors() {
      clearTimeout(this.supDebounce);
      this.supDebounce = setTimeout(() => {
        this.supervisorOptions.page = 1;
        this.fetchSupervisors();
      }, 350);
    },

    async fetchSupervisors() {
      this.loadingSupervisors = true;
      try {
        const params = new URLSearchParams({
          page: this.supervisorOptions.page,
          count: this.supervisorOptions.itemsPerPage,
        });
        if (this.supFilter.name) params.set("name", this.supFilter.name);
        if (this.supFilter.position)
          params.set("position", this.supFilter.position);
        if (this.supFilter.department)
          params.set("department", this.supFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council")
            params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.supervisorTotal = data.total || 0;
        this.supervisorItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchSupervisors error", err);
      } finally {
        this.loadingSupervisors = false;
      }
    },

    selectSupervisor(item) {
      this.form.supervisor = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position,
        facility: item.facility,
        grade: item.grade,
      };
      this.supervisorDialog = false;
    },

    clearSupervisor() {
      this.form.supervisor = {
        reference: null,
        display: "",
        position: "",
        facility: "",
        grade: "",
      };
    },

    // ── Location filter tree (shared with supervisor picker) ────────────
    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [], // lazy-loadable
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    fetchFilterChildren(item) {
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = [];
            this.filterTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchFilterChildren error", err));
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    openConfirmDialog() {
      this.formSubmitted = true;
      if (!this.form.supervisor.reference) {
        this.showSnackbar("Please select the new supervisor.", "error");
        return;
      }
      if (!this.form.date || this.form.date > this.today) {
        this.showSnackbar("Effective date cannot be in the future.", "error");
        return;
      }
      this.confirmDialog = true;
    },

    async applyTransfer() {
      if (!this.form.supervisor.reference) {
        this.showSnackbar("Please select the new supervisor.", "error");
        this.confirmDialog = false;
        return;
      }
      if (!this.form.date || this.form.date > this.today) {
        this.showSnackbar("Effective date cannot be in the future.", "error");
        this.confirmDialog = false;
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          request: this.transferId,
          supervisor: this.form.supervisor.reference,
          comments: this.form.comments,
          date: this.form.date,
        };
        this.afterSaveMessage = "Transfer applied successfully!";
        await this.processFHIR();
        this.confirmDialog = false;
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 300);
      } catch (error) {
        console.error("applyTransfer error:", error);
        this.showSnackbar(
          "Failed to apply transfer. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },
  },
};
</script>

